dplyr query

tic()
shared_rides &lt;- nyc_taxi |&gt; 
  group_by(year) |&gt; 
  summarize(total_rides = n(), 
            shared_rides = sum(passenger_count &gt; 1,
                               na.rm = TRUE)) |&gt; 
  mutate(percent_shared = (shared_rides / total_rides) * 100) |&gt; 
  collect()
toc()

