Calculate the percent of rides that are shared by year


library(dplyr)
nyc_taxi |&gt;                                                        
  group_by(year) |&gt; 
  summarize(
    total_rides = n(), 
    shared_rides = sum(passenger_count &gt; 1,
                       na.rm = TRUE)
    ) |&gt; 
  mutate(percent_shared = (shared_rides / total_rides) * 100) |&gt; 
  class()

